-- PT112-S3-Q24. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT112-S3-Q24$batch06$ AND q.stimulus=$batch06$A newspaper article on Britain's unions argued that their strength was declining. The article's evidence was the decreasing number and size of strikes, as if the reason for the unions' existence was to organize strikes. Surely, in a modern industrial society, the calling of a strike is evidence that the negotiating position of the union was too weak. Strong unions do not need to call strikes. They can concentrate their efforts on working with others in the labor market to achieve common goals, such as profitable and humane working conditions.$batch06$ AND q.prompt=$batch06$The argument criticizing the newspaper article employs which one of the following strategies?$batch06$ AND q.correct_choice=$batch06$C$batch06$) THEN RAISE EXCEPTION 'Question changed: PT112-S3-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT112-S3-Q24$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S3-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT112-S3-Q24$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$The article is wrong that Britain's unions are getting weaker.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Calling a strike is a sign a union's negotiating position was too weak. Strong unions do not need to strike.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The article and the author look at the same fact: fewer and smaller strikes. The article reads it as weakness. The author flips it: if strikes signal weakness, fewer strikes signal strength. Same evidence, opposite meaning.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Reinterpreting the article's evidence as showing the opposite of its conclusion.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT112-S3-Q24$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The author accepts that strikes are fewer and smaller. Only the meaning is disputed.$batch06$), ($batch06$B$batch06$, $batch06$No history of changes is laid out.$batch06$), ($batch06$C$batch06$, $batch06$The evidence is the drop in strikes. The article says it shows declining strength; the author says it shows the opposite.$batch06$), ($batch06$D$batch06$, $batch06$The article's motives never come up.$batch06$), ($batch06$E$batch06$, $batch06$Common goals are mentioned as what strong unions can pursue, but the argument's move is reinterpreting the strike numbers.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT112-S3-Q24$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
